public static int findNthLeapYear(int Y, int N) {
    int year = Y;
    // Find the first leap year >= Y
    while (!((year % 400 == 0) || (year % 4 == 0 && year % 100 != 0))) {
        year++;
    }
    int count = 1;
    while (count < N) {
        year++;
        if ((year % 400 == 0) || (year % 4 == 0 && year % 100 != 0)) {
            count++;
        }
    }
    return year;
}

