public int findLargestSubstring(java.util.List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        if (s.length() < minLen) {
            minLen = s.length();
        }
    }
    String first = strings.get(0);
    for (int L = minLen; L >= 1; L--) {
        java.util.List<java.util.Set<String>> sets = new java.util.ArrayList<>(strings.size());
        for (String s : strings) {
            java.util.Set<String> set = new java.util.HashSet<>();
            for (int i = 0; i + L <= s.length(); i++) {
                set.add(s.substring(i, i + L));
            }
            sets.add(set);
        }
        for (int i = 0; i + L <= first.length(); i++) {
            String sub = first.substring(i, i + L);
            String rev = new java.lang.StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (java.util.Set<String> set : sets) {
                if (!set.contains(sub) && !set.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return L;
            }
        }
    }
    return 0;
}

