            String key2 = coordToKey.apply(coord2);
            graph.putIfAbsent(key1, new java.util.ArrayList<>());
            graph.putIfAbsent(key2, new java.util.ArrayList<>());
            graph.get(key1).add(key2);
            graph.get(key2).add(key1);
        } else if (path.length == 2) {
            // Treat as indices into a list of nodes (not used in this implementation)
            // Skip or handle accordingly if needed
            // For safety, ignore such paths
        } else {
            // Unsupported path format; ignore
        }
    }

    // BFS to check connectivity
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        for (String neighbor : graph.getOrDefault(current, java.util.Collections.emptyList())) {
