public static String convertDatesToWeekdays(String date) {
    // Split the input string into month, day, and year components
    String[] parts = date.split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Input must be in the format \"MM dd yyyy\"");
    }
    int month = Integer.parseInt(parts[0]); // 1-12
    int day = Integer.parseInt(parts[1]);   // 1-31
    int year = Integer.parseInt(parts[2]);  // e.g., 1997

    // Map month number to month name
    String[] monthNames = {
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    };
    String monthName = monthNames[month - 1];

    // Use Calendar to determine the day of the week
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.set(java.util.Calendar.YEAR, year);
    cal.set(java.util.Calendar.MONTH, month - 1); // Calendar months are 0-based
    cal.set(java.util.Calendar.DAY_OF_MONTH, day);
    int dayOfWeek = cal.get(java.util.Calendar.DAY_OF_WEEK);

    // Map Calendar day of week to name
    String[] dayNames = {
        "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"
    };
    String weekday = dayNames[dayOfWeek - 1];

    // Construct the result string
    return monthName + " " + day + ", " + year + " is a " + weekday;
}

