public String sortString(String s) {
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.merge(c, 1, Integer::sum);
    }
    StringBuilder sb = new StringBuilder();
    int total = s.length();
    while (sb.length() < total) {
        // Ascending pass
        Character key = freq.firstKey();
        sb.append(key);
        int cnt = freq.get(key);
        if (cnt == 1) {
            freq.remove(key);
        } else {
            freq.put(key, cnt - 1);
        }
        char last = key;
        while (true) {
            Character next = freq.higherKey(last);
            if (next == null) break;
            sb.append(next);
            int ncnt = freq.get(next);
            if (ncnt == 1) {
                freq.remove(next);
            } else {
                freq.put(next, ncnt - 1);
            }
            last = next;
        }
        if (sb.length() == total) break;
        // Descending pass
        Character key2 = freq.lastKey();
