public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // DP sets for each subset size
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        // iterate k from current max down to 1
        for (int k = n - 1; k >= 1; k--) {
            if (dp[k - 1].isEmpty()) continue;
            for (int sum : dp[k - 1]) {
                dp[k].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

