public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    // dp[0] and dp[1] represent the minimum cost to reach step 0 and step 1 respectively.
    int prev2 = 0; // cost to reach step 0
    int prev1 = 0; // cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int cur = Math.min(prev2 + cost[i - 2], prev1 + cost[i - 1]);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

