public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int total = 1 << k;
    if (n < total) return false;
    int mask = 0;
    int maskAll = total - 1;
    boolean[] seen = new boolean[total];
    int seenCount = 0;
    for (int i = 0; i < n; i++) {
        mask = ((mask << 1) & maskAll) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[mask]) {
                seen[mask] = true;
                seenCount++;
                if (seenCount == total) return true;
            }
        }
    }
    return false;
}

