public int minInsertions(String s) {
    int insertions = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                // need an opening bracket before this
                insertions++;
                balance++; // after inserting '('
            }
            balance--; // match current ')'
        }
    }
    // any remaining unmatched '(' need closing brackets
    insertions += balance;
    return insertions;
}

