public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;
    Queue<Long> queue = new LinkedList<>();
    // Start BFS from each digit 0-9
    for (int d = 0; d <= 9; d++) {
        if (d == 0) {
            if (low == 0) result.add(0);
            continue;
        }
        queue.offer((long)d);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) continue;
        if (num >= low) result.add((int)num);
        int lastDigit = (int)(num % 10);
        // Next possible digits
        if (lastDigit > 0) {
            long nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) queue.offer(nextNum);
        }
        if (lastDigit < 9) {
            long nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) queue.offer(nextNum);
        }
    }
    Collections.sort(result);
    return result;
}

