public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (n / factor != 0) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        count += higher * factor;
        if (cur == 1) {
            count += lower + 1;
        } else if (cur > 1) {
            count += factor;
        }
        factor *= 10;
    }
    return (int) count;
}

