        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] h = new int[m][n];
    int[][] v = new int[m][n];
    int[][] d = new int[m][n];
    int[][] ad = new int[m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
