public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    int maxVal = A[n - 1];
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    int fullMask = (1 << n) - 1;
    int[][] dp = new int[1 << n][n + 1];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(dp[i], -1);
    }
    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int lastIdx) {
            if (mask == fullMask) return 1;
            int dpIdx = lastIdx + 1;
            if (dp[mask][dpIdx] != -1) return dp[mask][dpIdx];
            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (lastIdx != -1 && !isSquare[A[lastIdx] + A[i]]) continue;
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                count += applyAsInt(mask | (1 << i), i);
            }
            dp[mask][dpIdx] = count;
            return count;
        }
    };
    return dfs.applyAsInt(0, -1);
}

